-- ═════════ 0005_search.sql ═════════
-- Storefront search, filters and facets. SECURITY INVOKER: RLS limits results to published products for visitors.

create or replace function category_descendants(p_category uuid) returns setof uuid language sql stable as $$
  with recursive t as (
    select id from categories where id = p_category
    union all
    select c.id from categories c join t on c.parent_id = t.id
  ) select id from t
$$;

-- Lowest sellable price for a product (family price or cheapest active variant); null = quote only.
create or replace function product_display_price(p_product uuid) returns numeric language sql stable as $$
  select coalesce(
    (select base_price from products where id = p_product and not is_quote_only),
    (select min(v.price) from product_variants v join products p on p.id = v.product_id
      where v.product_id = p_product and v.is_active and v.price is not null and not p.is_quote_only))
$$;

-- p_filters example: {"size":["2\""],"grade":["304","316"]}  (OR within one attribute, AND across attributes)
create or replace function search_products(
  p_q text default null,
  p_category uuid default null,
  p_filters jsonb default '{}'::jsonb,
  p_availability text default null,       -- 'in_stock' | 'quote_only' | 'priced'
  p_flag text default null,               -- 'featured' | 'new' | 'offer'
  p_sort text default 'newest',           -- newest | name_asc | price_low | price_high | popular
  p_limit int default 24,
  p_offset int default 0
) returns table (id uuid, total bigint)
language plpgsql stable as $$
declare k text; vals text[]; q text := nullif(trim(p_q), '');
begin
  return query
  with filtered as (
    select p.id, p.name_en, p.published_at, p.view_count, product_display_price(p.id) as dprice
    from products p
    where p.status = 'published'
      and (p_category is null or p.category_id in (select category_descendants(p_category)))
      and (q is null or p.name_en ilike '%'||q||'%' or p.name_ar ilike '%'||q||'%' or p.sku ilike '%'||q||'%'
           or p.short_desc_en ilike '%'||q||'%' or p.description_en ilike '%'||q||'%'
           or exists (select 1 from product_variants v where v.product_id = p.id and v.sku ilike '%'||q||'%')
           or exists (select 1 from product_attribute_values a where a.product_id = p.id and (a.value_en ilike '%'||q||'%' or a.value_ar ilike '%'||q||'%'))
           or exists (select 1 from brands b where b.id = p.brand_id and b.name ilike '%'||q||'%'))
      and (p_flag is null or (p_flag = 'featured' and p.is_featured) or (p_flag = 'new' and p.is_new_arrival) or (p_flag = 'offer' and p.is_special_offer))
      and (p_availability is null
           or (p_availability = 'quote_only' and p.is_quote_only)
           or (p_availability = 'priced' and not p.is_quote_only)
           or (p_availability = 'in_stock' and exists (select 1 from variant_availability va where va.product_id = p.id and va.available > 0)))
      and not exists (
        select 1 from jsonb_each(coalesce(p_filters, '{}'::jsonb)) f
        where jsonb_typeof(f.value) = 'array' and jsonb_array_length(f.value) > 0
          and not exists (
            select 1 from product_attribute_values a join attribute_defs d on d.id = a.attribute_id
            where a.product_id = p.id and d.key = f.key and a.value_en in (select jsonb_array_elements_text(f.value))))
  )
  select f.id, count(*) over () as total from filtered f
  order by
    case when p_sort = 'name_asc' then f.name_en end asc,
    case when p_sort = 'price_low' then f.dprice end asc nulls last,
    case when p_sort = 'price_high' then f.dprice end desc nulls last,
    case when p_sort = 'popular' then f.view_count end desc,
    f.published_at desc nulls last, f.name_en
  limit least(greatest(p_limit,1),100) offset greatest(p_offset,0);
end $$;
grant execute on function search_products(text,uuid,jsonb,text,text,text,int,int) to anon, authenticated;

-- Facet counts for the filter sidebar (within category + search scope, ignoring other facet selections for simplicity).
create or replace function product_facets(p_q text default null, p_category uuid default null)
returns table (attr_key text, attr_name_en text, attr_name_ar text, value_en text, value_ar text, n bigint)
language sql stable as $$
  select d.key, d.name_en, d.name_ar, a.value_en, max(a.value_ar), count(distinct a.product_id)
  from product_attribute_values a
  join attribute_defs d on d.id = a.attribute_id and d.is_filterable
  join products p on p.id = a.product_id and p.status = 'published'
  where (p_category is null or p.category_id in (select category_descendants(p_category)))
    and (nullif(trim(p_q),'') is null or p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike '%'||trim(p_q)||'%')
  group by d.key, d.name_en, d.name_ar, d.sort_order, a.value_en
  order by d.sort_order, d.key, a.value_en
$$;
grant execute on function product_facets(text,uuid) to anon, authenticated;

-- Type-ahead suggestions: products (prefix matches first) and categories.
create or replace function search_suggestions(p_q text, p_limit int default 6)
returns table (kind text, id uuid, slug text, name_en text, name_ar text, image_path text)
language sql stable as $$
  (select 'product'::text, p.id, p.slug, p.name_en, p.name_ar,
          (select i.storage_path from product_images i where i.product_id = p.id order by i.is_primary desc, i.sort_order limit 1)
   from products p
   where p.status = 'published' and length(trim(p_q)) >= 2
     and (p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike trim(p_q)||'%')
   order by (p.name_en ilike trim(p_q)||'%') desc, p.view_count desc limit p_limit)
  union all
  (select 'category'::text, c.id, c.slug, c.name_en, c.name_ar, c.image_path
   from categories c
   where c.is_active and length(trim(p_q)) >= 2 and (c.name_en ilike '%'||trim(p_q)||'%' or c.name_ar ilike '%'||trim(p_q)||'%')
   limit 3)
$$;
grant execute on function search_suggestions(text,int) to anon, authenticated;

-- ═════════ 0006_rfq_respond.sql ═════════
-- Customer response to a quotation (by emailed token or while signed in). No direct table write is granted.
create or replace function respond_rfq(p_token uuid, p_accept boolean) returns text
language plpgsql security definer set search_path = public as $$
declare r rfqs%rowtype;
begin
  select * into r from rfqs where access_token = p_token for update;
  if not found then raise exception 'Quotation not found'; end if;
  if r.status <> 'quoted' then raise exception 'This quotation can no longer be changed'; end if;
  if r.quote_valid_until is not null and r.quote_valid_until < current_date then
    update rfqs set status = 'expired' where id = r.id;
    insert into rfq_events (rfq_id, event, detail) values (r.id, 'expired', 'Validity date passed');
    raise exception 'This quotation has expired; please request a new one';
  end if;
  update rfqs set status = case when p_accept then 'accepted'::rfq_status else 'rejected'::rfq_status end where id = r.id;
  insert into rfq_events (rfq_id, event, detail, actor) values (r.id, case when p_accept then 'customer_accepted' else 'customer_rejected' end, null, auth.uid());
  return case when p_accept then 'accepted' else 'rejected' end;
end $$;
grant execute on function respond_rfq(uuid, boolean) to anon, authenticated;

-- Mark overdue quotations as expired (call from a scheduled job or on admin page load).
create or replace function expire_overdue_quotations() returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not is_staff() then raise exception 'Not authorised'; end if;
  update rfqs set status = 'expired' where status = 'quoted' and quote_valid_until < current_date;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function expire_overdue_quotations() from public, anon;
grant execute on function expire_overdue_quotations() to authenticated;

-- ═════════ 0007_reports.sql ═════════
-- Reporting functions (staff only). Revenue excludes cancelled/refunded orders. All figures come from real rows.

create or replace function admin_sales_report(p_from date, p_to date, p_group text default 'day')
returns table (period date, orders bigint, subtotal numeric, vat numeric, total numeric, paid numeric)
language sql stable security definer set search_path = public as $$
  select date_trunc(case when p_group = 'month' then 'month' else 'day' end, o.created_at at time zone 'Asia/Riyadh')::date as period,
         count(*), coalesce(sum(o.subtotal),0), coalesce(sum(o.vat_total),0), coalesce(sum(o.grand_total),0), coalesce(sum(o.amount_paid),0)
  from orders o
  where is_staff() and o.status not in ('cancelled','refunded')
    and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 1
$$;

create or replace function admin_sales_by_product(p_from date, p_to date, p_limit int default 50)
returns table (product_id uuid, name text, sku text, units numeric, revenue numeric, cost numeric, profit numeric)
language sql stable security definer set search_path = public as $$
  -- cost/profit are computed ONLY on lines whose purchase cost was known when the order was placed
  select oi.product_id, max(oi.name_en), max(oi.sku), sum(oi.quantity), sum(oi.line_total),
         coalesce(sum(c.unit_cost * oi.quantity), 0), coalesce(sum(oi.line_total - c.unit_cost * oi.quantity) filter (where c.unit_cost is not null), 0)
  from order_items oi join orders o on o.id = oi.order_id left join order_item_costs c on c.order_item_id = oi.id
  where is_staff() and o.status not in ('cancelled','refunded') and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by oi.product_id order by sum(oi.line_total) desc limit least(p_limit, 500)
$$;

create or replace function admin_sales_by_category(p_from date, p_to date)
returns table (category text, units numeric, revenue numeric)
language sql stable security definer set search_path = public as $$
  select coalesce(cat.name_en, 'Uncategorised'), sum(oi.quantity), sum(oi.line_total)
  from order_items oi join orders o on o.id = oi.order_id
  left join products p on p.id = oi.product_id left join categories cat on cat.id = p.category_id
  where is_staff() and o.status not in ('cancelled','refunded') and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 3 desc
$$;

create or replace function admin_traffic(p_from date, p_to date)
returns table (day date, visitors bigint, page_views bigint, product_views bigint, searches bigint, whatsapp_clicks bigint, rfq_submits bigint)
language sql stable security definer set search_path = public as $$
  select d::date,
    count(distinct e.session_id) filter (where e.event is not null), count(*) filter (where e.event = 'page_view'), count(*) filter (where e.event = 'product_view'),
    count(*) filter (where e.event = 'search'), count(*) filter (where e.event = 'whatsapp_click'), count(*) filter (where e.event = 'rfq_submit')
  from generate_series(p_from, p_to, interval '1 day') d
  left join analytics_events e on (e.created_at at time zone 'Asia/Riyadh')::date = d::date
  where is_staff() group by d order by d
$$;

create or replace function admin_top_searches(p_from date, p_to date, p_limit int default 20)
returns table (query text, n bigint) language sql stable security definer set search_path = public as $$
  select lower(trim(e.query)), count(*) from analytics_events e
  where is_staff() and e.event = 'search' and e.query is not null and trim(e.query) <> '' and (e.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 2 desc limit least(p_limit, 100)
$$;

create or replace function admin_rfq_funnel(p_from date, p_to date)
returns table (status text, n bigint, quoted_value numeric) language sql stable security definer set search_path = public as $$
  select r.status::text, count(*), coalesce(sum(r.quoted_total),0) from rfqs r
  where is_staff() and (r.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to group by 1 order by 2 desc
$$;

do $$ declare f text; begin
  foreach f in array array['admin_sales_report(date,date,text)','admin_sales_by_product(date,date,int)','admin_sales_by_category(date,date)','admin_traffic(date,date)','admin_top_searches(date,date,int)','admin_rfq_funnel(date,date)'] loop
    execute format('revoke all on function %s from public, anon', f); execute format('grant execute on function %s to authenticated', f);
  end loop; end $$;

-- ═════════ 0008_grants.sql ═════════
-- Explicit API privileges, so the setup does not depend on Supabase's default grants (which have changed between releases).
-- These grants only make tables *reachable*; Row Level Security (migration 0004) still decides which rows each role may see or change.
grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

-- Functions the public storefront calls directly (everything else stays staff/authenticated-only, see 0004).
grant execute on function search_products(text,uuid,jsonb,text,text,text,int,int), product_facets(text,uuid), search_suggestions(text,int), public_best_sellers(int),
  submit_rfq(jsonb,jsonb), get_rfq_by_token(uuid), respond_rfq(uuid,boolean), track_event(text,text,text,uuid,uuid,text,text) to anon, authenticated;
grant execute on function is_staff(), is_admin(), setting_numeric(text,numeric), product_display_price(uuid), category_descendants(uuid), sku_in_use(text,uuid,uuid) to anon, authenticated;

-- ═════════ 0009_import_shared_file.sql ═════════
-- A staged import batch can carry ONE shared private file (e.g. a supplier's mill-test-certificate bundle) that is attached
-- to every product created from that batch. The file lives in the private product-mtc bucket.
alter table import_batches add column if not exists shared_file_path text;

-- ═════════ 0010_social_contact_certs.sql ═════════
-- Admin-managed contact widget (WhatsApp + call), social links, and certifications shown on product pages.

-- ───────── Floating contact widget (single row) ─────────
create table contact_widget (
  id smallint primary key default 1 check (id = 1),
  whatsapp_enabled boolean not null default true,
  whatsapp_number text not null default '' check (whatsapp_number ~ '^(\d{8,15})?$'),   -- international format, digits only, no +
  default_message_en text not null default 'Hello KANZ CORNER, I would like to enquire about your products.',
  default_message_ar text not null default 'مرحباً كنز كورنر، أود الاستفسار عن منتجاتكم.',
  icon_path text,                                   -- custom icon in bucket site-icons; null = built-in WhatsApp icon
  position text not null default 'right' check (position in ('left', 'right')),
  show_desktop boolean not null default true,
  show_mobile boolean not null default true,
  label_en text not null default 'Chat on WhatsApp',
  label_ar text not null default 'تواصل عبر واتساب',
  description_en text not null default 'Opens a WhatsApp chat with KANZ CORNER in a new tab',
  description_ar text not null default 'يفتح محادثة واتساب مع كنز كورنر في نافذة جديدة',
  menu_label_en text not null default 'Contact us',
  menu_label_ar text not null default 'تواصل معنا',
  show_call boolean not null default true,
  call_number text not null default '' check (call_number ~ '^(\+?\d{6,16})?$'),          -- empty = use the company phone setting
  updated_at timestamptz not null default now()
);
insert into contact_widget (id) values (1);
-- Carry over the WhatsApp number already stored in Company settings (it was public on the site already).
update contact_widget set whatsapp_number = coalesce((select regexp_replace(value #>> '{}', '\D', '', 'g') from site_settings where key = 'public.company_whatsapp'), '')
  where exists (select 1 from site_settings where key = 'public.company_whatsapp' and (value #>> '{}') ~ '^\+?\d{8,15}$');

-- ───────── Social links ─────────
create table social_links (
  id uuid primary key default gen_random_uuid(),
  platform text not null check (platform in ('instagram','facebook','linkedin','x','youtube','tiktok','snapchat','custom')),
  name text not null check (char_length(name) between 1 and 60),
  url text not null check (url ~* '^https://[^\s]+$' and char_length(url) <= 500),
  icon_path text,                                    -- uploaded icon (bucket site-icons); null = built-in icon for the platform
  accessible_label text not null check (char_length(accessible_label) between 1 and 120),
  sort_order int not null default 0,
  is_active boolean not null default true,
  show_header boolean not null default false,
  show_footer boolean not null default true,
  show_mobile_menu boolean not null default false,
  show_floating boolean not null default false,
  created_at timestamptz not null default now()
);
create index on social_links (sort_order);

-- ───────── Certifications (only what the business really holds; entered by staff) ─────────
create table certifications (
  id uuid primary key default gen_random_uuid(),
  name_en text not null, name_ar text,
  issuer text,
  reference_number text,
  valid_until date,
  document_path text,                                -- supporting document in bucket product-docs (public)
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
create table product_certifications (
  product_id uuid not null references products(id) on delete cascade,
  certification_id uuid not null references certifications(id) on delete cascade,
  primary key (product_id, certification_id)
);

alter table contact_widget enable row level security;
alter table social_links enable row level security;
alter table certifications enable row level security;
alter table product_certifications enable row level security;

create policy "contact_widget public read" on contact_widget for select using (true);
create policy "contact_widget staff update" on contact_widget for update using (is_staff()) with check (is_staff());
create policy "social_links public read" on social_links for select using (is_active or is_staff());
create policy "social_links staff insert" on social_links for insert with check (is_staff());
create policy "social_links staff update" on social_links for update using (is_staff()) with check (is_staff());
create policy "social_links staff delete" on social_links for delete using (is_staff());
create policy "certifications public read" on certifications for select using ((is_active and (valid_until is null or valid_until >= current_date)) or is_staff());
create policy "certifications staff insert" on certifications for insert with check (is_staff());
create policy "certifications staff update" on certifications for update using (is_staff()) with check (is_staff());
create policy "certifications admin delete" on certifications for delete using (is_admin());
create policy "product_certs public read" on product_certifications for select
  using (exists (select 1 from products p where p.id = product_id and p.status = 'published') or is_staff());
create policy "product_certs staff write" on product_certifications for all using (is_staff()) with check (is_staff());

-- Icon storage (public read by URL; only staff can write). SVGs are sanitised by the server before upload.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('site-icons', 'site-icons', true, 524288, array['image/png', 'image/webp', 'image/svg+xml'])
on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy "site icons staff write" on storage.objects for all
  using (bucket_id = 'site-icons' and is_staff()) with check (bucket_id = 'site-icons' and is_staff());

grant select on contact_widget, social_links, certifications, product_certifications to anon;
grant select, insert, update, delete on contact_widget, social_links, certifications, product_certifications to authenticated;

-- ═════════ 0011_quality_certifications.sql ═════════
-- Quality & Certifications: richer certification records, per-product approval evidence/scope, admin-only management, /quality footer link.

-- ───────── Certification records ─────────
alter table certifications
  add column if not exists logo_path text,                    -- official logo uploaded by an admin (bucket site-icons)
  add column if not exists description_en text,
  add column if not exists description_ar text,
  add column if not exists verification_url text,
  add column if not exists holder text,                       -- certificate holder / manufacturer
  add column if not exists scope text not null default 'company',
  add column if not exists issued_at date,
  add column if not exists show_on_quality boolean not null default true;
alter table certifications drop constraint if exists certifications_scope_check;
alter table certifications add constraint certifications_scope_check check (scope in ('company', 'manufacturer', 'product'));
alter table certifications drop constraint if exists certifications_verification_url_check;
alter table certifications add constraint certifications_verification_url_check check (verification_url is null or (verification_url ~* '^https://[^\s]+$' and char_length(verification_url) <= 500));
alter table certifications drop constraint if exists certifications_dates_check;
alter table certifications add constraint certifications_dates_check check (issued_at is null or valid_until is null or valid_until >= issued_at);

-- ───────── Product ↔ certification assignment (evidence and scope live here) ─────────
alter table product_certifications
  add column if not exists status text not null default 'pending',
  add column if not exists reference_number text,
  add column if not exists document_path text,                -- product-specific certificate PDF (bucket product-docs)
  add column if not exists verification_url text,
  add column if not exists scope_note text,                   -- e.g. "Sizes 2"–8" only"
  add column if not exists variant_ids uuid[] not null default '{}',   -- empty = all variants of the product
  add column if not exists updated_at timestamptz not null default now();
alter table product_certifications drop constraint if exists product_certifications_status_check;
alter table product_certifications add constraint product_certifications_status_check check (status in ('verified', 'pending', 'not_available', 'not_applicable'));
alter table product_certifications drop constraint if exists product_certifications_url_check;
alter table product_certifications add constraint product_certifications_url_check check (verification_url is null or (verification_url ~* '^https://[^\s]+$' and char_length(verification_url) <= 500));
alter table product_certifications drop constraint if exists product_certifications_note_check;
alter table product_certifications add constraint product_certifications_note_check check (scope_note is null or char_length(scope_note) <= 300);
-- Anything assigned before this migration stays 'pending' until an admin verifies it (nothing becomes public by accident).

-- ───────── Access: only administrators manage certifications; the public sees only live, verified data ─────────
drop policy if exists "certifications public read" on certifications;
drop policy if exists "certifications staff insert" on certifications;
drop policy if exists "certifications staff update" on certifications;
drop policy if exists "certifications admin delete" on certifications;
drop policy if exists "certifications admin insert" on certifications;
drop policy if exists "certifications admin update" on certifications;
create policy "certifications public read" on certifications for select
  using ((is_active and (valid_until is null or valid_until >= current_date) and (issued_at is null or issued_at <= current_date)) or is_staff());
create policy "certifications admin insert" on certifications for insert with check (is_admin());
create policy "certifications admin update" on certifications for update using (is_admin()) with check (is_admin());
create policy "certifications admin delete" on certifications for delete using (is_admin());

drop policy if exists "product_certs public read" on product_certifications;
drop policy if exists "product_certs staff write" on product_certifications;
drop policy if exists "product_certs admin write" on product_certifications;
create policy "product_certs public read" on product_certifications for select
  using ((status = 'verified' and exists (select 1 from products p where p.id = product_id and p.status = 'published')) or is_staff());
create policy "product_certs admin write" on product_certifications for all using (is_admin()) with check (is_admin());

-- ───────── Footer link to the new page (only if it is not there yet) ─────────
insert into menu_links (menu, label_en, label_ar, url, sort_order)
select 'footer_company', 'Quality & Certifications', 'الجودة والشهادات', '/quality', 15
where not exists (select 1 from menu_links where menu = 'footer_company' and url = '/quality');

-- ═════════ 0012_seo.sql ═════════
-- SEO: per-page social/noindex controls, category buying guides, slug-change redirects, extra measurement events.

alter table products
  add column if not exists og_title_en text, add column if not exists og_title_ar text,
  add column if not exists og_desc_en text, add column if not exists og_desc_ar text,
  add column if not exists og_image_path text,                      -- bucket product-images (or banners); null = first product image
  add column if not exists seo_noindex boolean not null default false;
alter table categories
  add column if not exists seo_noindex boolean not null default false,
  add column if not exists buying_guide_en text, add column if not exists buying_guide_ar text;

-- ───────── Old URL -> new URL (created automatically whenever a product or category slug changes) ─────────
create table if not exists slug_redirects (
  entity text not null check (entity in ('product', 'category')),
  old_slug text not null,
  new_slug text not null,
  created_at timestamptz not null default now(),
  primary key (entity, old_slug)
);
alter table slug_redirects enable row level security;
drop policy if exists "slug_redirects public read" on slug_redirects;
create policy "slug_redirects public read" on slug_redirects for select using (true);
drop policy if exists "slug_redirects admin write" on slug_redirects;
create policy "slug_redirects admin write" on slug_redirects for all using (is_admin()) with check (is_admin());
grant select on slug_redirects to anon;
grant select, insert, update, delete on slug_redirects to authenticated;

create or replace function record_slug_change() returns trigger language plpgsql security definer set search_path = public as $$
declare ent text := tg_argv[0];
begin
  if new.slug is distinct from old.slug then
    delete from slug_redirects where entity = ent and old_slug = new.slug;                       -- the new address is live, never a redirect source
    update slug_redirects set new_slug = new.slug where entity = ent and new_slug = old.slug;    -- keep chains one hop long
    insert into slug_redirects (entity, old_slug, new_slug) values (ent, old.slug, new.slug)
      on conflict (entity, old_slug) do update set new_slug = excluded.new_slug;
  end if;
  return new;
end $$;
drop trigger if exists products_slug_redirect on products;
create trigger products_slug_redirect after update of slug on products for each row execute function record_slug_change('product');
drop trigger if exists categories_slug_redirect on categories;
create trigger categories_slug_redirect after update of slug on categories for each row execute function record_slug_change('category');

-- ───────── More measurable actions (still anonymous, first-party) ─────────
alter table analytics_events drop constraint if exists analytics_events_event_check;
alter table analytics_events add constraint analytics_events_event_check
  check (event in ('page_view','product_view','search','banner_impression','banner_click','add_to_cart','rfq_submit','whatsapp_click','phone_click','datasheet_download'));

create or replace function track_event(p_event text, p_session text, p_path text default null, p_product uuid default null, p_banner uuid default null, p_query text default null, p_lang text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_event not in ('page_view','product_view','search','banner_impression','banner_click','add_to_cart','whatsapp_click','phone_click','datasheet_download') then return; end if;   -- rfq_submit is recorded by submit_rfq itself
  if p_session is null or length(p_session) > 64 then return; end if;
  insert into analytics_events (event, session_id, path, product_id, banner_id, query, lang)
  values (p_event, p_session, left(p_path, 300), p_product, p_banner, left(p_query, 200), left(p_lang, 5));
  if p_event = 'product_view' and p_product is not null then update products set view_count = view_count + 1 where id = p_product; end if;
  if p_event = 'banner_impression' and p_banner is not null then update banners set impressions = impressions + 1 where id = p_banner; end if;
  if p_event = 'banner_click' and p_banner is not null then update banners set clicks = clicks + 1 where id = p_banner; end if;
end $$;

-- Traffic report: add phone clicks and datasheet downloads
drop function if exists admin_traffic(date, date);
create or replace function admin_traffic(p_from date, p_to date)
returns table (day date, visitors bigint, page_views bigint, product_views bigint, searches bigint, whatsapp_clicks bigint, rfq_submits bigint, phone_clicks bigint, datasheet_downloads bigint)
language sql stable security definer set search_path = public as $$
  select d::date,
    count(distinct e.session_id) filter (where e.event is not null), count(*) filter (where e.event = 'page_view'), count(*) filter (where e.event = 'product_view'),
    count(*) filter (where e.event = 'search'), count(*) filter (where e.event = 'whatsapp_click'), count(*) filter (where e.event = 'rfq_submit'),
    count(*) filter (where e.event = 'phone_click'), count(*) filter (where e.event = 'datasheet_download')
  from generate_series(p_from, p_to, interval '1 day') d
  left join analytics_events e on (e.created_at at time zone 'Asia/Riyadh')::date = d::date
  where is_staff() group by d order by d
$$;
grant execute on function admin_traffic(date, date) to authenticated;

-- ───────── Buying guides (general selection advice; only fills categories that have none yet) ─────────
update categories set buying_guide_en = $kb$Choose a pipe by service first: fluid, operating temperature and pressure, and any corrosion risk. Carbon steel suits many general and utility services; stainless and duplex grades are selected where corrosion resistance matters. Confirm the material specification (for example ASTM A106, A53 or API 5L), whether the pipe is seamless or welded, the nominal size, the schedule or wall thickness, and the end finish (plain or bevelled) before you order. Ask for the mill test certificate if your project requires material traceability.$kb$, buying_guide_ar = $kb$اختر الأنبوب بحسب ظروف التشغيل أولاً: نوع المائع ودرجة الحرارة والضغط ومخاطر التآكل. يناسب الصلب الكربوني كثيراً من الخدمات العامة، بينما تُختار أنواع الستانلس ستيل والدوبلكس عندما تكون مقاومة التآكل مهمة. قبل الطلب، حدد مواصفة المادة (مثل ASTM A106 أو A53 أو API 5L)، وهل الأنبوب بدون لحام أم ملحوم، والمقاس الاسمي، والسماكة أو الـ Schedule، ونوع الطرف (عادي أو مشطوف). اطلب شهادة اختبار المصنع (MTC) إذا كان مشروعك يتطلب تتبّع المواد.$kb$ where slug = 'pipes' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Match a fitting to the pipe it joins: the same nominal size, material grade and schedule or wall thickness. Butt-weld fittings (elbows, tees, reducers, caps) are welded into the line and are common for permanent, higher-pressure piping; check the standard (such as ASME B16.9), the radius of elbows (long or short) and the end bevel. Tell us the angle, size and any reduction (for example 6 in x 4 in) so we can quote the correct item.$kb$, buying_guide_ar = $kb$يجب أن تطابق الوصلة الأنبوب الذي تربطه من حيث المقاس الاسمي ودرجة المادة والسماكة أو الـ Schedule. تُلحم وصلات اللحام الطرفي (الأكواع والتيهات والمخفضات والأغطية) داخل الخط وهي شائعة في التمديدات الدائمة ذات الضغوط الأعلى؛ تحقق من المواصفة (مثل ASME B16.9) ونصف قطر الكوع (طويل أو قصير) ونوع الشطف. أخبرنا بالزاوية والمقاس وأي تخفيض (مثل 6 بوصة × 4 بوصة) لنقدّم لك السعر للصنف الصحيح.$kb$ where slug = 'pipe-fittings' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Forged fittings are normally used on smaller-bore, higher-pressure lines. Decide the connection first: threaded (NPT) or socket-weld. Then confirm the pressure class, which is commonly 2000, 3000, 6000 or 9000 depending on the connection, and the material grade and standard (for example ASME B16.11). Pressure class must suit the design pressure of the line, so please share the service conditions and the size when you request a quotation.$kb$, buying_guide_ar = $kb$تُستخدم الوصلات المطروقة عادةً في الخطوط الصغيرة القطر ذات الضغوط الأعلى. حدد نوع التوصيل أولاً: مسنّن (NPT) أو لحام مقبس (Socket Weld). ثم أكّد فئة الضغط (تشيع الفئات 2000 و3000 و6000 و9000 بحسب نوع التوصيل) ودرجة المادة والمواصفة (مثل ASME B16.11). يجب أن تناسب فئة الضغط ضغط التصميم للخط، لذا يرجى إرسال ظروف التشغيل والمقاس عند طلب عرض السعر.$kb$ where slug = 'forged-fittings' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Grooved couplings and fittings join pipe ends that have been cut or rolled with a groove, so they can be assembled and dismantled without welding. Confirm the pipe outside diameter and material, the pressure rating required by your system, the coupling type (rigid or flexible) and the gasket material suited to the fluid and temperature. Where you need documentation, ask us which test or approval documents we hold for the exact product and size.$kb$, buying_guide_ar = $kb$تربط الوصلات المخددة نهايات الأنابيب التي تم عمل أخدود لها بالقطع أو بالدرفلة، ويمكن تركيبها وفكّها دون لحام. أكّد القطر الخارجي للأنبوب ومادته، وتصنيف الضغط المطلوب لنظامك، ونوع الوصلة (ثابتة أو مرنة)، ومادة الجوان المناسبة للمائع ودرجة الحرارة. وإذا كنت تحتاج إلى مستندات، فاسألنا عن شهادات الاختبار أو الاعتمادات المتوفرة لدينا للصنف والمقاس المحدد.$kb$ where slug = 'copper-grooved-fittings' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Select plastic piping by material and service: HDPE for buried and flexible lines, PVC and CPVC for water and chemical services within their temperature limits, and PPR for hot and cold water systems. Check the pressure rating (PN), the size, the jointing method (fusion, solvent cement or threaded) and the standard the project requires. Temperature lowers the allowable pressure of plastics, so share your operating conditions when you ask for a quotation.$kb$, buying_guide_ar = $kb$اختر أنظمة الأنابيب البلاستيكية بحسب المادة والخدمة: HDPE للخطوط المدفونة والمرنة، وPVC وCPVC لخدمات المياه والمواد الكيميائية ضمن حدود الحرارة المسموحة، وPPR لشبكات المياه الساخنة والباردة. تحقق من تصنيف الضغط (PN) والمقاس وطريقة الوصل (لحام حراري أو لصق بالمذيب أو مسنّن) والمواصفة التي يطلبها المشروع. ترتفع الحرارة فتنخفض قدرة التحمّل للضغط في البلاستيك، لذا أرسل لنا ظروف التشغيل عند طلب السعر.$kb$ where slug = 'plastic-fittings' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$A flange must match its mating flange in standard, pressure class, size and facing. Confirm the standard (such as ASME B16.5), the class (150, 300, 600 and so on), the type (weld neck, slip-on, socket weld, threaded, blind, lap joint), the face (raised or flat) and the material. Weld-neck flanges are usually chosen for demanding services; slip-on flanges are easier to fit on lower-pressure lines. Remember to order the matching gaskets and bolting.$kb$, buying_guide_ar = $kb$يجب أن يطابق الفلنج الفلنج المقابل له في المواصفة وفئة الضغط والمقاس ونوع الوجه. أكّد المواصفة (مثل ASME B16.5) والفئة (150 أو 300 أو 600 وغيرها) والنوع (رقبة لحام أو انزلاقي أو لحام مقبس أو مسنّن أو أعمى أو لاب جوينت) والوجه (بارز أو مسطح) والمادة. تُختار فلنجات رقبة اللحام عادةً للخدمات الصعبة، أما الانزلاقية فتركيبها أسهل على الخطوط الأقل ضغطاً. ولا تنسَ طلب الجوانات والمسامير المناسبة.$kb$ where slug = 'flanges' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Choose the valve by its job: gate and ball valves for isolation, globe valves for throttling, check valves to stop reverse flow, and butterfly valves for larger lines. Confirm the size, pressure class, end connection (flanged, threaded, welded or wafer), the body and trim material for the fluid, and the seat or seal material. Tell us the service, pressure and temperature so we can quote a suitable valve.$kb$, buying_guide_ar = $kb$اختر الصمام بحسب وظيفته: صمامات البوابة والكرة للعزل، وصمامات الكروي (غلوب) للتحكم في التدفق، وصمامات عدم الرجوع لمنع التدفق العكسي، وصمامات الفراشة للخطوط الكبيرة. أكّد المقاس وفئة الضغط ونوع التوصيل (فلنج أو مسنّن أو لحام أو ويفر) ومادة الجسم والأجزاء الداخلية المناسبة للمائع ومادة المقعد أو الإحكام. أخبرنا بنوع الخدمة والضغط ودرجة الحرارة لنقدّم لك صماماً مناسباً.$kb$ where slug = 'valves' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$Bolting must suit the flange and the service. Check the thread size and length, the material grade (carbon steel, alloy or stainless), the coating if corrosion protection is needed, and the matching nuts and washers. Stud bolts are normally supplied with two nuts. For flanged joints, confirm the number and size of bolts for the flange class, and order spare gaskets together with the bolting.$kb$, buying_guide_ar = $kb$يجب أن تناسب المسامير الفلنج والخدمة. تحقق من مقاس السن والطول ودرجة المادة (صلب كربوني أو سبائك أو ستانلس ستيل) والطلاء إذا لزمت الحماية من التآكل، مع الصواميل والوردات المناسبة. تُورَّد المسامير المسننة (Stud) عادةً مع صامولتين. وللوصلات الفلنجية، أكّد عدد المسامير ومقاسها بحسب فئة الفلنج، واطلب الجوانات مع المسامير.$kb$ where slug = 'fasteners' and buying_guide_en is null and buying_guide_ar is null;
update categories set buying_guide_en = $kb$A gasket must suit the flange face, the pressure class and the fluid: spiral-wound and ring-type joints are used in higher-pressure services, while non-metallic sheet gaskets suit lower pressures. For pressure gauges, confirm the dial size, pressure range (the working pressure should sit within the middle of the scale), connection thread and position, and whether a liquid-filled case is needed for vibration.$kb$, buying_guide_ar = $kb$يجب أن يناسب الجوان وجه الفلنج وفئة الضغط والمائع: تُستخدم الجوانات الحلزونية وجوانات الحلقة (RTJ) في الخدمات ذات الضغط الأعلى، بينما تناسب الجوانات غير المعدنية الضغوط الأقل. وبالنسبة لمقاييس الضغط، أكّد قطر الميناء ومدى الضغط (ويفضّل أن يقع ضغط التشغيل في منتصف المقياس) ومقاس سن التوصيل واتجاهه، وهل تحتاج إلى علبة مملوءة بسائل للحد من أثر الاهتزاز.$kb$ where slug = 'gaskets-gauges' and buying_guide_en is null and buying_guide_ar is null;
update categories c set buying_guide_en = p.buying_guide_en, buying_guide_ar = p.buying_guide_ar from categories p where c.slug = 'grooved-fittings' and p.slug = 'copper-grooved-fittings' and c.buying_guide_en is null;

-- ═════════ 0013_homepage_sections.sql ═════════
-- Homepage redesign: new section types the admin can enable, disable and reorder like the existing ones.
alter table homepage_sections drop constraint if exists homepage_sections_type_check;
alter table homepage_sections add constraint homepage_sections_type_check check (type in (
  'hero','category_cards','featured_products','new_arrivals','best_sellers','special_offers','brands','announcement','why_us','rfq_cta','custom_html',
  'quick_filters','industries','certifications','rfq_steps','recently_viewed','promo_banners'));

-- Add the new blocks once, in a sensible position (existing order and texts are left untouched).
insert into homepage_sections (type, title_en, title_ar, sort_order, is_enabled)
select v.type, v.title_en, v.title_ar, v.sort_order, true
from (values
  ('promo_banners',   null::text, null::text, 12),
  ('quick_filters',   'Browse by material & standard', 'تصفح حسب المادة والمواصفة', 15),
  ('industries',      'Products for your sector', 'منتجات لقطاعك', 25),
  ('certifications',  'Certificates & approvals', 'الشهادات والاعتمادات', 75),
  ('rfq_steps',       'Request a quotation in 3 steps', 'اطلب عرض سعر في 3 خطوات', 35),
  ('recently_viewed', 'Recently viewed', 'شوهدت مؤخراً', 87)
) as v(type, title_en, title_ar, sort_order)
where not exists (select 1 from homepage_sections h where h.type = v.type);

-- ═════════ 0014_catalogue_extraction.sql ═════════
-- Reusable manufacturer-catalogue extraction & import.
-- Nothing here publishes data by itself: extracted records wait in a staff-only review area until approved and imported.

-- ───────── Manufacturers (the existing brands table) ─────────
alter table brands add column if not exists country text, add column if not exists notes text;

-- ───────── Shared product families across manufacturers (never merges manufacturer records) ─────────
create table if not exists product_families (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9-]{2,80}$'),
  name_en text not null, name_ar text,
  product_type text,                           -- e.g. elbow_90, tee, weldolet
  category_id uuid references categories(id) on delete set null,
  created_at timestamptz not null default now()
);

alter table products
  add column if not exists family_id uuid references product_families(id) on delete set null,
  add column if not exists manufacturer_ref text,            -- manufacturer's own reference, kept separate from our SKU
  add column if not exists country_of_origin text,           -- only when the catalogue states it
  add column if not exists applications_en text, add column if not exists applications_ar text,
  add column if not exists specs jsonb not null default '{}'::jsonb,   -- {standards:[{code,scope}], materials:[{type,grades}], notes:[...]} with source refs
  add column if not exists source_ref jsonb;                  -- {source_id, title, pages:[...]}
create index if not exists products_family_idx on products(family_id);

-- ───────── Selectable options (dependent: only combinations that exist as variants can be chosen) ─────────
create table if not exists product_options (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  key text not null check (key ~ '^[a-z][a-z0-9_]{0,39}$'),
  name_en text not null, name_ar text,
  sort_order int not null default 0,
  unique (product_id, key)
);
create table if not exists product_option_values (
  id uuid primary key default gen_random_uuid(),
  option_id uuid not null references product_options(id) on delete cascade,
  value text not null check (char_length(value) between 1 and 80),
  label_en text not null, label_ar text,
  sort_order int not null default 0,
  unique (option_id, value)
);
alter table product_variants
  add column if not exists options jsonb not null default '{}'::jsonb,   -- {"connection":"socket_weld","class":"3000","size":"1/2"}
  add column if not exists manufacturer_code text,
  add column if not exists weight_kg numeric(12,4) check (weight_kg is null or weight_kg >= 0),
  add column if not exists source_page int;
create unique index if not exists variants_product_options_uq on product_variants (product_id, (options::text)) where options <> '{}'::jsonb;

-- ───────── Engineering dimension tables (symbols are per table: "A" on one drawing is not "A" on another) ─────────
create table if not exists dimension_tables (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  title_en text not null, title_ar text,
  columns jsonb not null,                       -- [{key, symbol, label_en, label_ar, unit}]
  applies jsonb not null default '{}'::jsonb,   -- options this table applies to, e.g. {"connection":"socket_weld"}
  drawing_path text,                            -- bucket product-images
  notes jsonb not null default '[]'::jsonb,     -- footnotes / restrictions, verbatim
  source_page int,
  sort_order int not null default 0,
  check (jsonb_typeof(columns) = 'array' and jsonb_array_length(columns) between 1 and 40)
);
create table if not exists dimension_rows (
  id uuid primary key default gen_random_uuid(),
  table_id uuid not null references dimension_tables(id) on delete cascade,
  match jsonb not null,                         -- which variants the row describes, e.g. {"size":"1/2","class":"3000"}
  "values" jsonb not null,                      -- {"A":"15.9","B":"..."} exactly as printed
  sort_order int not null default 0
);
create index if not exists dimension_tables_product_idx on dimension_tables(product_id);
create index if not exists dimension_rows_table_idx on dimension_rows(table_id);

-- ───────── Extraction workspace (staff only) ─────────
create table if not exists catalogue_sources (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid references brands(id) on delete set null,
  title text not null,
  file_path text,                               -- bucket catalogue-sources (private)
  file_size bigint, page_count int check (page_count is null or page_count between 1 and 2000),
  status text not null default 'uploaded' check (status in ('uploaded','processing','reviewing','done')),
  notes text,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists catalogue_pages (
  id uuid primary key default gen_random_uuid(),
  source_id uuid not null references catalogue_sources(id) on delete cascade,
  page_no int not null check (page_no >= 1),
  status text not null default 'pending' check (status in ('pending','rendered','extracted','needs_review','skipped','failed')),
  image_path text,                              -- bucket import-staging
  text_content text,
  method text check (method in ('text','vision','manual')),
  skip_reason text, error text,
  products_found int not null default 0,
  updated_at timestamptz not null default now(),
  unique (source_id, page_no)
);
create table if not exists extracted_products (
  id uuid primary key default gen_random_uuid(),
  source_id uuid not null references catalogue_sources(id) on delete cascade,
  data jsonb not null,                          -- proposed product incl. options, variants, dimension tables, images, refs (validated in the app)
  pages int[] not null default '{}',
  confidence numeric(4,3) check (confidence is null or confidence between 0 and 1),
  status text not null default 'pending' check (status in ('pending','approved','rejected','imported')),
  duplicate_of uuid references products(id) on delete set null,
  duplicate_info jsonb,
  imported_product_id uuid references products(id) on delete set null,
  reviewed_by uuid references profiles(id), reviewed_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists extracted_products_source_idx on extracted_products(source_id, status);
create table if not exists extraction_warnings (
  id uuid primary key default gen_random_uuid(),
  source_id uuid not null references catalogue_sources(id) on delete cascade,
  extracted_product_id uuid references extracted_products(id) on delete cascade,
  page_no int,
  severity text not null default 'warning' check (severity in ('info','warning','error')),
  code text not null, message text not null,
  resolved boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists extraction_warnings_source_idx on extraction_warnings(source_id);
create table if not exists catalogue_import_runs (
  id uuid primary key default gen_random_uuid(),
  source_id uuid references catalogue_sources(id) on delete set null,
  created_by uuid references profiles(id),
  summary jsonb not null,                       -- {imported, skipped, errors, product_ids}
  created_at timestamptz not null default now()
);

-- ───────── Access ─────────
alter table product_families enable row level security;
alter table product_options enable row level security;
alter table product_option_values enable row level security;
alter table dimension_tables enable row level security;
alter table dimension_rows enable row level security;
alter table catalogue_sources enable row level security;
alter table catalogue_pages enable row level security;
alter table extracted_products enable row level security;
alter table extraction_warnings enable row level security;
alter table catalogue_import_runs enable row level security;

create or replace function product_is_public(p uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from products where id = p and status = 'published')
$$;

drop policy if exists "families public read" on product_families;
create policy "families public read" on product_families for select using (true);
drop policy if exists "families staff write" on product_families;
create policy "families staff write" on product_families for all using (is_staff()) with check (is_staff());

drop policy if exists "options public read" on product_options;
create policy "options public read" on product_options for select using (product_is_public(product_id) or is_staff());
drop policy if exists "options staff write" on product_options;
create policy "options staff write" on product_options for all using (is_staff()) with check (is_staff());
drop policy if exists "option values public read" on product_option_values;
create policy "option values public read" on product_option_values for select
  using (exists (select 1 from product_options o where o.id = option_id and (product_is_public(o.product_id) or is_staff())));
drop policy if exists "option values staff write" on product_option_values;
create policy "option values staff write" on product_option_values for all using (is_staff()) with check (is_staff());

drop policy if exists "dimension tables public read" on dimension_tables;
create policy "dimension tables public read" on dimension_tables for select using (product_is_public(product_id) or is_staff());
drop policy if exists "dimension tables staff write" on dimension_tables;
create policy "dimension tables staff write" on dimension_tables for all using (is_staff()) with check (is_staff());
drop policy if exists "dimension rows public read" on dimension_rows;
create policy "dimension rows public read" on dimension_rows for select
  using (exists (select 1 from dimension_tables t where t.id = table_id and (product_is_public(t.product_id) or is_staff())));
drop policy if exists "dimension rows staff write" on dimension_rows;
create policy "dimension rows staff write" on dimension_rows for all using (is_staff()) with check (is_staff());

do $$ declare t text; begin
  foreach t in array array['catalogue_sources','catalogue_pages','extracted_products','extraction_warnings','catalogue_import_runs'] loop
    execute format('drop policy if exists "%1$s staff only" on %1$I', t);
    execute format('create policy "%1$s staff only" on %1$I for all using (is_staff()) with check (is_staff())', t);
  end loop;
end $$;

grant select on product_families, product_options, product_option_values, dimension_tables, dimension_rows to anon;
grant select, insert, update, delete on product_families, product_options, product_option_values, dimension_tables, dimension_rows,
  catalogue_sources, catalogue_pages, extracted_products, extraction_warnings, catalogue_import_runs to authenticated;

-- Private bucket for uploaded catalogue PDFs (manufacturer documents: never public)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('catalogue-sources', 'catalogue-sources', false, 52428800, array['application/pdf'])
on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types, public = false;
drop policy if exists "catalogue sources staff" on storage.objects;
create policy "catalogue sources staff" on storage.objects for all
  using (bucket_id = 'catalogue-sources' and is_staff()) with check (bucket_id = 'catalogue-sources' and is_staff());

-- ───────── Import one approved extracted product atomically (all or nothing) ─────────
-- p is prepared and validated by the application; the product is created as an unpublished, quote-only DRAFT.
create or replace function catalogue_import_product(p_extracted uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_product uuid; v_family uuid; v_opt uuid; o jsonb; v jsonb; t jsonb; r jsonb; i jsonb; v_table uuid; n int;
  v_status text;
begin
  if not is_staff() then raise exception 'Not authorised'; end if;
  select status into v_status from extracted_products where id = p_extracted for update;
  if v_status is null then raise exception 'Extracted record not found'; end if;
  if v_status <> 'approved' then raise exception 'Only approved records can be imported (status: %)', v_status; end if;

  if p ? 'family' and p->'family' is not null then
    insert into product_families (slug, name_en, name_ar, product_type, category_id)
    values (p->'family'->>'slug', p->'family'->>'name_en', p->'family'->>'name_ar', p->'family'->>'product_type', nullif(p->'family'->>'category_id','')::uuid)
    on conflict (slug) do update set name_en = product_families.name_en   -- keep the existing family as it is
    returning id into v_family;
  end if;

  insert into products (slug, name_en, name_ar, short_desc_en, short_desc_ar, description_en, description_ar, category_id, brand_id, status, is_quote_only,
                        unit, family_id, manufacturer_ref, country_of_origin, applications_en, applications_ar, specs, source_ref, seo_title_en, seo_title_ar, seo_desc_en, seo_desc_ar)
  values (p->'product'->>'slug', p->'product'->>'name_en', p->'product'->>'name_ar', p->'product'->>'short_desc_en', p->'product'->>'short_desc_ar',
          p->'product'->>'description_en', p->'product'->>'description_ar', nullif(p->'product'->>'category_id','')::uuid, nullif(p->'product'->>'brand_id','')::uuid,
          'draft', true, coalesce(p->'product'->>'unit','pcs'), v_family, p->'product'->>'manufacturer_ref', p->'product'->>'country_of_origin',
          p->'product'->>'applications_en', p->'product'->>'applications_ar', coalesce(p->'product'->'specs','{}'::jsonb), p->'product'->'source_ref',
          p->'product'->>'seo_title_en', p->'product'->>'seo_title_ar', p->'product'->>'seo_desc_en', p->'product'->>'seo_desc_ar')
  returning id into v_product;

  n := 0;
  for o in select * from jsonb_array_elements(coalesce(p->'options','[]'::jsonb)) loop
    insert into product_options (product_id, key, name_en, name_ar, sort_order) values (v_product, o->>'key', o->>'name_en', o->>'name_ar', n) returning id into v_opt;
    insert into product_option_values (option_id, value, label_en, label_ar, sort_order)
      select v_opt, x->>'value', x->>'label_en', x->>'label_ar', ord - 1 from jsonb_array_elements(o->'values') with ordinality as e(x, ord);
    n := n + 1;
  end loop;

  n := 0;
  for v in select * from jsonb_array_elements(coalesce(p->'variants','[]'::jsonb)) loop
    insert into product_variants (product_id, sku, label_en, label_ar, size, grade, schedule, pressure_class, material, price, is_active, sort_order, options, manufacturer_code, weight_kg, source_page)
    values (v_product, v->>'sku', v->>'label_en', v->>'label_ar', v->>'size', v->>'grade', v->>'schedule', v->>'pressure_class', v->>'material', null, true, n,
            coalesce(v->'options','{}'::jsonb), v->>'manufacturer_code', nullif(v->>'weight_kg','')::numeric, nullif(v->>'source_page','')::int);
    n := n + 1;
  end loop;

  n := 0;
  for t in select * from jsonb_array_elements(coalesce(p->'dimension_tables','[]'::jsonb)) loop
    insert into dimension_tables (product_id, title_en, title_ar, columns, applies, drawing_path, notes, source_page, sort_order)
    values (v_product, t->>'title_en', t->>'title_ar', t->'columns', coalesce(t->'applies','{}'::jsonb), t->>'drawing_path', coalesce(t->'notes','[]'::jsonb), nullif(t->>'source_page','')::int, n)
    returning id into v_table;
    insert into dimension_rows (table_id, match, "values", sort_order)
      select v_table, x->'match', x->'values', ord - 1 from jsonb_array_elements(coalesce(t->'rows','[]'::jsonb)) with ordinality as e(x, ord);
    n := n + 1;
  end loop;

  for i in select * from jsonb_array_elements(coalesce(p->'images','[]'::jsonb)) loop
    insert into product_images (product_id, storage_path, alt_en, alt_ar, sort_order, is_primary, needs_hires)
    values (v_product, i->>'storage_path', i->>'alt_en', i->>'alt_ar', coalesce((i->>'sort_order')::int, 0), coalesce((i->>'is_primary')::boolean, false), coalesce((i->>'needs_hires')::boolean, false));
  end loop;

  update extracted_products set status = 'imported', imported_product_id = v_product, updated_at = now() where id = p_extracted;
  return v_product;
end $$;
revoke all on function catalogue_import_product(uuid, jsonb) from public, anon;
grant execute on function catalogue_import_product(uuid, jsonb) to authenticated;

-- ═════════ 0015_product_families.sql ═════════
-- 0015: one product page per product family with a manufacturer (brand) selector.
-- Product family -> manufacturer offerings (existing products, one per brand) -> variants -> dimension tables / drawings / documents.
-- Additive only: no existing product data is changed, except the Delcorte brand display name (decision: "JD Delcorte").

-- ───────── Family page content ─────────
alter table product_families
  add column if not exists short_desc_en text, add column if not exists short_desc_ar text,
  add column if not exists description_en text, add column if not exists description_ar text,
  add column if not exists image_path text,                       -- KANZ's own photo (manufacturer photos are not used)
  add column if not exists status text not null default 'draft',
  add column if not exists published_at timestamptz,
  add column if not exists sort_order int not null default 0,
  add column if not exists seo_title_en text, add column if not exists seo_title_ar text,
  add column if not exists seo_desc_en text, add column if not exists seo_desc_ar text,
  add column if not exists seo_noindex boolean not null default false,
  add column if not exists updated_at timestamptz not null default now();
do $$ begin
  alter table product_families add constraint product_families_status_check check (status in ('draft', 'published'));
exception when duplicate_object then null; end $$;

-- ───────── Offering link: a product joins its family page only after an admin confirms it ─────────
alter table products
  add column if not exists family_link text not null default 'suggested',
  add column if not exists family_sort int not null default 0;
do $$ begin
  alter table products add constraint products_family_link_check check (family_link in ('suggested', 'confirmed', 'rejected'));
exception when duplicate_object then null; end $$;
create index if not exists products_family_idx on products(family_id) where family_id is not null;

-- ───────── Match suggestions (import / scan), reviewed in Admin -> Product families ─────────
create table if not exists family_link_suggestions (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  family_id uuid not null references product_families(id) on delete cascade,
  confidence text not null check (confidence in ('exact', 'likely', 'uncertain')),
  reasons jsonb not null default '[]',
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decided_by uuid references profiles(id), decided_at timestamptz,
  created_at timestamptz not null default now(),
  unique (product_id, family_id)
);

-- ───────── One URL namespace: /[lang]/product/<slug> serves a family or a product, so slugs must never clash ─────────
create or replace function check_family_product_slug() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'product_families' and exists (select 1 from products where slug = new.slug) then
    raise exception 'The address "%" is already used by a product', new.slug using errcode = '23505';
  elsif tg_table_name = 'products' and exists (select 1 from product_families where slug = new.slug) then
    raise exception 'The address "%" is already used by a product family', new.slug using errcode = '23505';
  end if;
  return new;
end $$;
drop trigger if exists product_families_slug_unique on product_families;
create trigger product_families_slug_unique before insert or update of slug on product_families for each row execute function check_family_product_slug();
drop trigger if exists products_family_slug_unique on products;
create trigger products_family_slug_unique before insert or update of slug on products for each row execute function check_family_product_slug();
-- a family's old address keeps working after a rename (same redirect table as products, same URL namespace)
drop trigger if exists product_families_slug_redirect on product_families;
create trigger product_families_slug_redirect after update of slug on product_families for each row execute function record_slug_change('product');
drop trigger if exists product_families_updated on product_families;
create trigger product_families_updated before update on product_families for each row execute function set_updated_at();

-- ───────── Access ─────────
drop policy if exists "families public read" on product_families;
create policy "families public read" on product_families for select using (status = 'published' or is_staff());
alter table family_link_suggestions enable row level security;
drop policy if exists "family suggestions staff only" on family_link_suggestions;
create policy "family suggestions staff only" on family_link_suggestions for all using (is_staff()) with check (is_staff());
grant select, insert, update, delete on family_link_suggestions to authenticated;

-- ───────── Brand display name (owner's decision) ─────────
update brands set name = 'JD Delcorte' where slug = 'delcorte' and name = 'Delcorte';
update products set name_en = 'JD ' || name_en
 where brand_id = (select id from brands where slug = 'delcorte') and name_en like 'Delcorte %' and status = 'draft';

-- ═════════ 0016_family_listings.sql ═════════
-- 0016: listings show ONE entry per product family.
-- A published product is listed as its family when it is a confirmed offering of a PUBLISHED family; otherwise it is listed on its own.
-- Search, filters, facet counts, suggestions and category counts all count these listing entries, so totals and pagination
-- count families, not manufacturer records. No product data is changed.

-- The family a product is listed under (null = listed on its own). SECURITY DEFINER only to read the family status cheaply; returns ids only.
create or replace function product_listing_family(p_product uuid) returns uuid language sql stable security definer set search_path = public as $$
  select f.id from products p join product_families f on f.id = p.family_id
  where p.id = p_product and p.family_link = 'confirmed' and p.status = 'published' and f.status = 'published'
$$;
grant execute on function product_listing_family(uuid) to anon, authenticated;

drop function if exists search_products(text, uuid, jsonb, text, text, text, int, int);
create function search_products(
  p_q text default null,
  p_category uuid default null,
  p_filters jsonb default '{}'::jsonb,
  p_availability text default null,
  p_flag text default null,
  p_sort text default 'newest',
  p_limit int default 24,
  p_offset int default 0
) returns table (id uuid, total bigint, family_id uuid)
language plpgsql stable as $$
declare q text := nullif(trim(p_q), '');
begin
  return query
  with filtered as (
    select p.id, p.name_en, p.published_at, p.view_count, product_display_price(p.id) as dprice, p.family_sort,
           product_listing_family(p.id) as fam
    from products p
    where p.status = 'published'
      and (p_category is null or p.category_id in (select category_descendants(p_category)))
      and (q is null or p.name_en ilike '%'||q||'%' or p.name_ar ilike '%'||q||'%' or p.sku ilike '%'||q||'%'
           or p.short_desc_en ilike '%'||q||'%' or p.description_en ilike '%'||q||'%'
           or exists (select 1 from product_variants v where v.product_id = p.id and (v.sku ilike '%'||q||'%' or v.manufacturer_code ilike '%'||q||'%'))
           or exists (select 1 from product_attribute_values a where a.product_id = p.id and (a.value_en ilike '%'||q||'%' or a.value_ar ilike '%'||q||'%'))
           or exists (select 1 from brands b where b.id = p.brand_id and b.name ilike '%'||q||'%')
           or exists (select 1 from product_families f where f.id = p.family_id and f.status = 'published' and (f.name_en ilike '%'||q||'%' or f.name_ar ilike '%'||q||'%')))
      and (p_flag is null or (p_flag = 'featured' and p.is_featured) or (p_flag = 'new' and p.is_new_arrival) or (p_flag = 'offer' and p.is_special_offer))
      and (p_availability is null
           or (p_availability = 'quote_only' and p.is_quote_only)
           or (p_availability = 'priced' and not p.is_quote_only)
           or (p_availability = 'in_stock' and exists (select 1 from variant_availability va where va.product_id = p.id and va.available > 0)))
      and not exists (
        select 1 from jsonb_each(coalesce(p_filters, '{}'::jsonb)) f
        where jsonb_typeof(f.value) = 'array' and jsonb_array_length(f.value) > 0
          and not exists (
            select 1 from product_attribute_values a join attribute_defs d on d.id = a.attribute_id
            where a.product_id = p.id and d.key = f.key and a.value_en in (select jsonb_array_elements_text(f.value))))
  ),
  -- one row per listing entry: the family's first offering (by admin order) represents it; sort keys use the family's best values
  grouped as (
    select distinct on (coalesce(f.fam, f.id)) f.id, f.fam,
           min(f.name_en) over w as name_en, max(f.published_at) over w as published_at, sum(f.view_count) over w as view_count, min(f.dprice) over w as dprice
    from filtered f
    window w as (partition by coalesce(f.fam, f.id))
    order by coalesce(f.fam, f.id), f.family_sort, f.name_en
  )
  select g.id, count(*) over () as total, g.fam from grouped g
  order by
    case when p_sort = 'name_asc' then g.name_en end asc,
    case when p_sort = 'price_low' then g.dprice end asc nulls last,
    case when p_sort = 'price_high' then g.dprice end desc nulls last,
    case when p_sort = 'popular' then g.view_count end desc,
    g.published_at desc nulls last, g.name_en
  limit least(greatest(p_limit,1),100) offset greatest(p_offset,0);
end $$;
grant execute on function search_products(text,uuid,jsonb,text,text,text,int,int) to anon, authenticated;

-- facet counts = number of listing entries (a family counts once even if three brands carry the value)
create or replace function product_facets(p_q text default null, p_category uuid default null)
returns table (attr_key text, attr_name_en text, attr_name_ar text, value_en text, value_ar text, n bigint)
language sql stable as $$
  select d.key, d.name_en, d.name_ar, a.value_en, max(a.value_ar), count(distinct coalesce(product_listing_family(p.id), p.id))
  from product_attribute_values a
  join attribute_defs d on d.id = a.attribute_id and d.is_filterable
  join products p on p.id = a.product_id and p.status = 'published'
  where (p_category is null or p.category_id in (select category_descendants(p_category)))
    and (nullif(trim(p_q),'') is null or p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike '%'||trim(p_q)||'%')
  group by d.key, d.name_en, d.name_ar, d.sort_order, a.value_en
  order by d.sort_order, d.key, a.value_en
$$;
grant execute on function product_facets(text,uuid) to anon, authenticated;

-- type-ahead: families first (one suggestion per family), then standalone products, then categories
drop function if exists search_suggestions(text, int);
create function search_suggestions(p_q text, p_limit int default 6)
returns table (kind text, id uuid, slug text, name_en text, name_ar text, image_path text)
language sql stable as $$
  with hits as (
    select p.id, p.slug, p.name_en, p.name_ar, p.view_count, product_listing_family(p.id) as fam,
           (select i.storage_path from product_images i where i.product_id = p.id order by i.is_primary desc, i.sort_order limit 1) as img
    from products p
    where p.status = 'published' and length(trim(p_q)) >= 2
      and (p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike trim(p_q)||'%'
           or exists (select 1 from product_families f where f.id = p.family_id and (f.name_en ilike '%'||trim(p_q)||'%' or f.name_ar ilike '%'||trim(p_q)||'%')))
  ),
  entries as (
    select distinct on (coalesce(h.fam, h.id))
           case when h.fam is null then 'product' else 'family' end as kind, coalesce(h.fam, h.id) as id,
           coalesce(f.slug, h.slug) as slug, coalesce(f.name_en, h.name_en) as name_en, coalesce(f.name_ar, h.name_ar) as name_ar,
           coalesce(f.image_path, h.img) as image_path, h.view_count
    from hits h left join product_families f on f.id = h.fam
    order by coalesce(h.fam, h.id), h.view_count desc
  )
  (select e.kind, e.id, e.slug, e.name_en, e.name_ar, e.image_path from entries e
   order by (e.name_en ilike trim(p_q)||'%') desc, e.view_count desc limit p_limit)
  union all
  (select 'category'::text, c.id, c.slug, c.name_en, c.name_ar, c.image_path
   from categories c
   where c.is_active and length(trim(p_q)) >= 2 and (c.name_en ilike '%'||trim(p_q)||'%' or c.name_ar ilike '%'||trim(p_q)||'%')
   limit 3)
$$;
grant execute on function search_suggestions(text,int) to anon, authenticated;

-- listing entries per active category, including its sub-categories (a family counts once per category)
create or replace function category_listing_counts() returns table (category_id uuid, n bigint)
language sql stable as $$
  with recursive tree as (
    select c.id as root, c.id from categories c where c.is_active
    union all
    select t.root, c.id from categories c join tree t on c.parent_id = t.id
  )
  select t.root, count(distinct coalesce(product_listing_family(p.id), p.id))
  from tree t join products p on p.category_id = t.id and p.status = 'published'
  group by t.root
$$;
grant execute on function category_listing_counts() to anon, authenticated;

-- number of listing entries in the whole shop (homepage counter)
create or replace function listing_count() returns bigint language sql stable as $$
  select count(distinct coalesce(product_listing_family(p.id), p.id)) from products p where p.status = 'published'
$$;
grant execute on function listing_count() to anon, authenticated;

